{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2187-02-17 08:00:00",
      "speaker": "Doctor",
      "text": "Good morning. I’m Dr. Lee, one of your surgical team doctors. I understand you’ve been having facial swelling, headaches, and nausea again?"
    },
    {
      "turn_number": 2,
      "time": "2187-02-17 08:01:30",
      "speaker": "Patient",
      "text": "Yes, it’s been getting worse over the last few days. Especially when I lie back or lift my arms. My neck feels so tight."
    },
    {
      "turn_number": 3,
      "time": "2187-02-17 08:02:45",
      "speaker": "Doctor",
      "text": "That sounds consistent with your SVC syndrome. Your last procedure didn’t fully resolve the narrowing in your superior vena cava, and we think it’s gotten tighter again."
    },
    {
      "turn_number": 4,
      "time": "2187-02-17 08:04:00",
      "speaker": "Patient",
      "text": "So what happens now? Last time they couldn’t place the stent."
    },
    {
      "turn_number": 5,
      "time": "2187-02-17 08:05:15",
      "speaker": "Doctor",
      "text": "Because the blockage was too tight for a stent, we’ve scheduled you for surgery today. We’ll open the SVC and use a patch to widen it, along with removing the clot in your right subclavian vein."
    },
    {
      "turn_number": 6,
      "time": "2187-02-17 08:06:30",
      "speaker": "Patient",
      "text": "Surgery? That sounds serious. Is it safe?"
    },
    {
      "turn_number": 7,
      "time": "2187-02-17 08:07:45",
      "speaker": "Doctor",
      "text": "It’s a major procedure, but necessary. The vascular and cardiothoracic teams will be working together. We’ve reviewed your history, including your HIT, so we’ll use fondaparinux instead of heparin."
    },
    {
      "turn_number": 8,
      "time": "2187-02-17 08:09:00",
      "speaker": "Patient",
      "text": "Okay… I trust you. I just want this swelling to stop."
    },
    {
      "turn_number": 9,
      "time": "2187-02-17 13:30:00",
      "speaker": "Doctor",
      "text": "Hi, it’s Dr. Lee again. The surgery went well. You had a SVC endarterectomy and a bovine pericardial patch placed. No complications."
    },
    {
      "turn_number": 10,
      "time": "2187-02-17 13:31:30",
      "speaker": "Patient",
      "text": "Thank you… I feel groggy, but my head doesn’t hurt as much."
    },
    {
      "turn_number": 11,
      "time": "2187-02-17 13:33:00",
      "speaker": "Doctor",
      "text": "That’s a good sign. We’ve extubated you, and you’re on a ventilator no longer. We’re watching your vitals closely in the ICU."
    },
    {
      "turn_number": 12,
      "time": "2187-02-17 13:34:30",
      "speaker": "Patient",
      "text": "Will I be here long?"
    },
    {
      "turn_number": 13,
      "time": "2187-02-17 13:36:00",
      "speaker": "Doctor",
      "text": "We’ll keep you in the ICU for a few days, then move you to the VICU. You’ll start on fondaparinux for blood thinning and metoprolol for blood pressure."
    },
    {
      "turn_number": 14,
      "time": "2187-02-18 09:00:00",
      "speaker": "Doctor",
      "text": "Morning. Your chest X-ray shows no pneumothorax, and your chest tubes were removed. The right upper lobe opacity is improving—likely atelectasis from surgery."
    },
    {
      "turn_number": 15,
      "time": "2187-02-18 09:01:30",
      "speaker": "Patient",
      "text": "I’m breathing easier. But I feel a little anxious being in the hospital."
    },
    {
      "turn_number": 16,
      "time": "2187-02-18 09:03:00",
      "speaker": "Doctor",
      "text": "I understand. We’ve restarted your diazepam and benadryl for anxiety. The chronic pain team also recommended morphine elixir—it’s helping with your comfort?"
    },
    {
      "turn_number": 17,
      "time": "2187-02-18 09:04:30",
      "speaker": "Patient",
      "text": "Yes, it’s better. Thank you."
    },
    {
      "turn_number": 18,
      "time": "2187-02-19 22:30:00",
      "speaker": "Doctor",
      "text": "We saw your X-ray. There’s a small pleural effusion and some mediastinal widening. It could be post-op changes, but we’re watching closely for bleeding."
    },
    {
      "turn_number": 19,
      "time": "2187-02-19 22:32:00",
      "speaker": "Patient",
      "text": "Is that dangerous?"
    },
    {
      "turn_number": 20,
      "time": "2187-02-19 22:33:30",
      "speaker": "Doctor",
      "text": "Not necessarily. It’s common after this type of surgery. We’ll repeat imaging if needed. Your blood cultures were negative—no infection."
    },
    {
      "turn_number": 21,
      "time": "2187-02-20 10:00:00",
      "speaker": "Doctor",
      "text": "Your abdominal X-ray shows mild distention. Could be ileus, but we’re not concerned yet. You’re still tolerating food okay?"
    },
    {
      "turn_number": 22,
      "time": "2187-02-20 10:01:30",
      "speaker": "Patient",
      "text": "I’ve been bloated, but I’m eating. I did have some blood in my stool yesterday."
    },
    {
      "turn_number": 23,
      "time": "2187-02-20 10:03:00",
      "speaker": "Doctor",
      "text": "We saw that. Your C. diff test was negative, so it’s likely from your Crohn’s. We’ll keep monitoring."
    },
    {
      "turn_number": 24,
      "time": "2187-02-21 08:00:00",
      "speaker": "Doctor",
      "text": "We did a CT scan because you had pain in your left groin. It showed contrast leaking from your line and a small hematoma."
    },
    {
      "turn_number": 25,
      "time": "2187-02-21 08:01:30",
      "speaker": "Patient",
      "text": "Oh no—does that mean it has to come out?"
    },
    {
      "turn_number": 26,
      "time": "2187-02-21 08:03:00",
      "speaker": "Doctor",
      "text": "Yes, we removed the line. You don’t need it anymore, and it’s safer to avoid further bleeding. The hematoma is small and should absorb on its own."
    },
    {
      "turn_number": 27,
      "time": "2187-02-21 08:04:30",
      "speaker": "Patient",
      "text": "Okay. My pain’s better now."
    },
    {
      "turn_number": 28,
      "time": "2187-02-21 15:00:00",
      "speaker": "Doctor",
      "text": "Your hemoglobin dropped a bit during the transfusion yesterday. You had a reaction—severe left lower quadrant pain?"
    },
    {
      "turn_number": 29,
      "time": "2187-02-21 15:01:30",
      "speaker": "Patient",
      "text": "Yes, sharp pain. But it went away after they stopped the transfusion."
    },
    {
      "turn_number": 30,
      "time": "2187-02-21 15:03:00",
      "speaker": "Doctor",
      "text": "We think it was related to the line issue, not the blood itself. You’re now anemic, so we gave you Epogen under the skin and oral lasix to help."
    },
    {
      "turn_number": 31,
      "time": "2187-02-21 15:04:30",
      "speaker": "Patient",
      "text": "Will I need another transfusion?"
    },
    {
      "turn_number": 32,
      "time": "2187-02-21 15:06:00",
      "speaker": "Doctor",
      "text": "Not right now. Your levels are stabilizing. We’ll check again tomorrow."
    },
    {
      "turn_number": 33,
      "time": "2187-02-22 09:00:00",
      "speaker": "Doctor",
      "text": "Good news—your hemoglobin is up to 26.5%. You’re doing well. Physical therapy saw you and says you can walk independently."
    },
    {
      "turn_number": 34,
      "time": "2187-02-22 09:01:30",
      "speaker": "Patient",
      "text": "That’s great. When can I go home?"
    },
    {
      "turn_number": 35,
      "time": "2187-02-22 09:03:00",
      "speaker": "Doctor",
      "text": "Possibly tomorrow. We’ll discharge you with pain and anxiety meds, fondaparinux, and a follow-up with your PCP in four days."
    },
    {
      "turn_number": 36,
      "time": "2187-02-22 09:04:30",
      "speaker": "Patient",
      "text": "I’m nervous about driving or lifting. My sternum feels tender."
    },
    {
      "turn_number": 37,
      "time": "2187-02-22 09:06:00",
      "speaker": "Doctor",
      "text": "You’ll need to follow sternal precautions for 10 weeks—no lifting over 10 pounds, no pushing or pulling. And no driving for at least four weeks, especially on narcotics."
    },
    {
      "turn_number": 38,
      "time": "2187-02-22 09:07:30",
      "speaker": "Patient",
      "text": "Got it. What about showering?"
    },
    {
      "turn_number": 39,
      "time": "2187-02-22 09:09:00",
      "speaker": "Doctor",
      "text": "You can shower—just let water run over the incision. No baths for six weeks. Call us if you see redness, drainage, fever, or sudden swelling."
    },
    {
      "turn_number": 40,
      "time": "2187-02-23 08:00:00",
      "speaker": "Doctor",
      "text": "Good morning. You’re cleared for discharge today. Your facial swelling is much improved, and you’re tolerating a regular diet."
    },
    {
      "turn_number": 41,
      "time": "2187-02-23 08:01:30",
      "speaker": "Patient",
      "text": "I feel so much better. Thank you."
    },
    {
      "turn_number": 42,
      "time": "2187-02-23 08:03:00",
      "speaker": "Doctor",
      "text": "You’re welcome. Here’s your discharge medication list. Fondaparinux daily, metoprolol twice a day, morphine for pain as needed."
    },
    {
      "turn_number": 43,
      "time": "2187-02-23 08:04:30",
      "speaker": "Patient",
      "text": "The morphine elixir has helped a lot. Can I keep using it?"
    },
    {
      "turn_number": 44,
      "time": "2187-02-23 08:06:00",
      "speaker": "Doctor",
      "text": "Yes, as needed. But your PCP will reassess in four days. We’ve also added ranitidine for stomach protection and docusate for constipation."
    },
    {
      "turn_number": 45,
      "time": "2187-02-23 08:07:30",
      "speaker": "Patient",
      "text": "And my Crohn’s symptoms?"
    },
    {
      "turn_number": 46,
      "time": "2187-02-23 08:09:00",
      "speaker": "Doctor",
      "text": "We’re managing that conservatively. Continue your usual meds. If diarrhea or bleeding worsens, call your gastroenterologist."
    },
    {
      "turn_number": 47,
      "time": "2187-02-23 08:10:30",
      "speaker": "Patient",
      "text": "I will. And if I feel anxious at home?"
    },
    {
      "turn_number": 48,
      "time": "2187-02-23 08:12:00",
      "speaker": "Doctor",
      "text": "Use the diazepam or diphenhydramine as prescribed. And don’t hesitate to call if anything feels off."
    },
    {
      "turn_number": 49,
      "time": "2187-02-23 08:13:30",
      "speaker": "Patient",
      "text": "Thank you, Dr. Lee. I really appreciate everything."
    },
    {
      "turn_number": 50,
      "time": "2187-02-23 08:15:00",
      "speaker": "Doctor",
      "text": "You did great. Take care, and we’ll see you in follow-up if needed."
    },
    {
      "turn_number": 51,
      "time": "2187-02-23 08:16:30",
      "speaker": "Patient",
      "text": "One last thing—should I watch for blood in my stool again?"
    },
    {
      "turn_number": 52,
      "time": "2187-02-23 08:18:00",
      "speaker": "Doctor",
      "text": "Occasional blood can happen with Crohn’s, but if it’s heavy or persistent, get it checked. Your recent guaiac-positive stools weren’t from a serious bleed."
    },
    {
      "turn_number": 53,
      "time": "2187-02-23 08:19:30",
      "speaker": "Patient",
      "text": "Okay, that helps. I’ll keep an eye on it."
    },
    {
      "turn_number": 54,
      "time": "2187-02-23 08:21:00",
      "speaker": "Doctor",
      "text": "Also, wear your surgical bra and avoid sleeping on your stomach. It helps protect your sternum."
    },
    {
      "turn_number": 55,
      "time": "2187-02-23 08:22:30",
      "speaker": "Patient",
      "text": "I’ll do that. Thank you for explaining everything so clearly."
    },
    {
      "turn_number": 56,
      "time": "2187-02-23 08:24:00",
      "speaker": "Doctor",
      "text": "You’re very welcome. You’ve been through a lot, but you’re on the mend. We’re discharging you in good condition."
    },
    {
      "turn_number": 57,
      "time": "2187-02-23 08:25:30",
      "speaker": "Patient",
      "text": "I’m ready to go home. Just glad this is behind me."
    },
    {
      "turn_number": 58,
      "time": "2187-02-23 08:27:00",
      "speaker": "Doctor",
      "text": "Take it easy. Rest, follow the instructions, and call us with any concerns."
    },
    {
      "turn_number": 59,
      "time": "2187-02-23 08:28:30",
      "speaker": "Patient",
      "text": "I will. Thanks again."
    },
    {
      "turn_number": 60,
      "time": "2187-02-23 08:30:00",
      "speaker": "Doctor",
      "text": "Take care. You’re all set to go home with home services for support."
    }
  ],
  "summary": {
    "admission_start": "2187-02-17 07:15:00",
    "admission_end": "2187-02-23 16:59:00",
    "summary_paragraph": "A 54-year-old woman with a history of Crohn’s disease, short bowel syndrome, and SVC syndrome was admitted with worsening facial and neck swelling, headaches, nausea, and blurred vision due to recurrent superior vena cava obstruction. An open SVC reconstruction with bovine pericardial patch and endarterectomy was performed successfully. Postoperatively, she developed a hematoma at the left groin line site requiring removal, and experienced a drop in hemoglobin requiring transfusion and subsequent Epogen administration. Her pain and anxiety were managed with morphine elixir, benzodiazepines, and antihistamines. She improved steadily, was ambulating independently, and was discharged home in good condition with sternal precautions, anticoagulation, and follow-up planned with her PCP in four days.",
    "problems": [
      "Compression of vein",
      "Hematoma complicating a procedure",
      "Other and unspecified postsurgical nonabsorption",
      "Unspecified pleural effusion",
      "Chronic venous embolism and thrombosis of other thoracic veins",
      "Chronic venous embolism and thrombosis of subclavian veins",
      "Chronic venous embolism and thrombosis of internal jugular veins",
      "Abdominal pain, right lower quadrant",
      "Nonspecific abnormal findings in stool contents",
      "Unspecified acquired hypothyroidism",
      "Myalgia and myositis, unspecified",
      "Iron deficiency anemia, unspecified",
      "Unspecified essential hypertension",
      "Personal history of allergy to other specified medicinal agents"
    ]
  }
}
